import {formatComplex,decomposeCharacters,decomposeCorepresentationCharacters,directProduct} from './engine.js';

const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={view:'workbench',mode:'sg',group:null,k:[0,0,0],doubleValued:false,tab:'characters',result:null,resultGroup:null,busy:false,dbMode:'sg',dbQuery:'',dbPage:0,dbType:'all',angle:.48,tilt:.42,bandText:''};
let databases={},worker,requestId=0,toastTimer;
const labels={workbench:['对称性工作台','从空间群到磁空间群，探索晶体的对称性与不可约表示。'],database:['群数据库','检索空间群、磁空间群与磁点群，查看原始对称操作。'],products:['直积分解','解析两个 k 星的表示张量积，追踪输出波矢与不可约分量。'],bands:['能带特征标匹配','读取本地 trace 文件，或输入已按当前操作排序的能带特征标。'],docs:['方法与使用说明','坐标约定、数值验证、数据来源与当前版本的功能范围。']};
const lattices={TricPrim:'三斜 · P',MonoPrim:'单斜 · P',MonoBase:'单斜 · C',OrthPrim:'正交 · P',OrthBase:'正交 · C',OrthBody:'正交 · I',OrthFace:'正交 · F',TetrPrim:'四方 · P',TetrBody:'四方 · I',TrigPrim:'三方 · R',HexaPrim:'六方 · P',CubiPrim:'立方 · P',CubiFace:'立方 · F',CubiBody:'立方 · I'};
const gid=(g=state.group,mode=state.mode)=>mode==='sg'?String(g.number):g.id;
const gtitle=(g=state.group)=>g.bcSymbol||g.symbol;
const list=mode=>mode==='sg'?databases.sg.groups:mode==='msg'?databases.msg.groups:databases.mpg.points;
const complex=x=>Array.isArray(x)?{re:x[0],im:x[1]}:typeof x==='number'?{re:x,im:0}:x;
const decomposeBand=(chars,r)=>r.corepresentations.length?decomposeCorepresentationCharacters(chars,r.corepresentations):decomposeCharacters(chars,r.irreps);
const cf=x=>{try{return formatComplex(complex(x),4)}catch{return JSON.stringify(x)}};
const norm=x=>Math.abs(x)<1e-8?0:Number(x.toFixed(6));
function fraction(n){if(!Number.isFinite(n))return '?';for(let d=1;d<=24;d++)if(Math.abs(n*d-Math.round(n*d))<1e-7)return d===1?String(Math.round(n)):Math.round(n*d)+'/'+d;return String(norm(n));}
function parseNumber(s){if(!/^\s*[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?(?:\s*\/\s*[+-]?(?:\d+\.?\d*|\.\d+))?\s*$/.test(s))throw new Error('坐标仅支持数字、小数或分数，例如 1/2。');const a=s.split('/').map(Number);const n=a.length===2?a[0]/a[1]:a[0];if(!Number.isFinite(n)||Math.abs(n)>100)throw new Error('坐标必须为 −100 到 100 之间的有限数值。');return n;}
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3200);}
function download(content,name,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function showError(message){const dest=$('#calculation-error')||$('#app');dest.innerHTML=`<div class="notice error" role="alert">${esc(message)}</div>`;}
function setView(view){state.view=view;$('#breadcrumb').textContent=labels[view][0];$('#page-title').innerHTML=esc(labels[view][0])+(view==='workbench'?'<span class="beta">浏览器版</span>':'');$('#page-subtitle').textContent=labels[view][1];$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===view));render();}
function resultMatches(){return state.result&&gid()===gid(state.resultGroup,state.resultMode)&&state.mode===state.resultMode&&state.doubleValued===state.result.doubleValued&&state.k.every((x,i)=>Math.abs(x-state.result.k[i])<1e-8);}
function modeButtons(mode,attr='mode'){return `<div class="segment">${[['sg','空间群 SG'],['msg','磁空间群 MSG'],['mpg','磁点群 MPG']].map(([m,t])=>`<button data-${attr}="${m}" class="${m===mode?'active':''}">${t}</button>`).join('')}</div>`;}
function selectGroup(g,mode=state.mode){state.group=g;state.mode=mode;state.k=[0,0,0];state.result=null;state.tab='characters';render();}
function render(){if(!state.group)return;if(state.view==='workbench')renderWorkbench();else if(state.view==='database')renderDatabase();else if(state.view==='docs')renderDocs();else if(state.view==='products')renderProducts();else if(state.view==='bands')renderBands();}
function renderWorkbench(){const g=state.group;const current=resultMatches();const r=current?state.result:null;$('#app').innerHTML=`<div class="workspace-grid"><section class="panel"><div class="panel-top"><div class="panel-title"><span class="step">01</span> 定义对称性</div><span class="subtle">PARAMETERS</span></div><div class="panel-body">${modeButtons(state.mode)}
 <label class="field-label" for="group-search">${state.mode==='sg'?'空间群编号或符号':state.mode==='msg'?'磁空间群 · BNS / OG 编号':'磁点群编号或符号'}<span>${state.mode==='sg'?'1 — 230':state.mode==='msg'?'1,651 MAGNETIC GROUPS':'122 MAGNETIC POINT GROUPS'}</span></label>
 <div class="search-wrap"><div class="group-input"><input id="group-search" autocomplete="off" aria-label="搜索并选择群" value="${esc(gid(g))}   ${esc(gtitle(g))}"><span>⌕</span></div><div id="group-options" class="search-list hidden"></div></div>
 <div class="group-info"><strong>${esc(gtitle(g))}</strong><span class="tag">${esc(lattices[g.lattice]||g.lattice)}</span><span class="tag">${state.mode==='sg'?esc(g.pointGroup):'Type '+['','I','II','III','IV'][g.type]}</span>${g.ogId?`<span class="tag">OG ${g.ogId}</span>`:''}</div>
 <div class="field-label">波矢 k<span>BC 原胞倒易分数坐标</span></div><div class="coords">${state.k.map((v,i)=>`<div class="coord"><label for="k-${i}">k<sub>${['x','y','z'][i]}</sub></label><input id="k-${i}" aria-label="k ${['x','y','z'][i]}" value="${fraction(v)}" ${state.mode==='mpg'?'disabled':''}></div>`).join('')}</div>
 <div class="presets">${(g.kpoints||[{label:'Γ',coordinates:[0,0,0]}]).slice(0,10).map((p,i)=>`<button data-preset="${i}" title="${esc((p.bzTypes||[]).join(', '))}: (${p.coordinates.map(fraction).join(', ')})" class="${p.coordinates.every((x,j)=>Math.abs(x-state.k[j])<1e-8)?'active':''}">${esc(p.label)}</button>`).join('')}<button id="generic-k" ${state.mode==='mpg'?'disabled':''}>一般 k</button></div>
 <div class="spin-row"><div class="field-label">表示类型<small>单值 / 自旋双值</small></div><div class="segment"><button data-spin="false" class="${!state.doubleValued?'active':''}">单值 · 无 SOC</button><button data-spin="true" class="${state.doubleValued?'active':''}">双值 · SOC</button></div></div>
 <button id="calculate" class="primary" ${state.busy?'disabled':''}><span>${state.busy?'<i class="spinner"></i>正在计算…':'计算不可约表示'}</span><span>→</span></button>
 <p class="form-note">坐标按 BC 约定。D₁、D₂… 为本页面数值编号，并非 BC / Bilbao 标准标签。</p><div id="calculation-error"></div></div></section>
 <section class="panel"><div class="panel-top"><div class="panel-title"><span class="step">02</span> 倒易空间</div><span class="subtle">k-STAR EXPLORER</span></div><div class="visual-body"><span class="viz-tag">${esc(g.lattice)} / RECIPROCAL CELL</span><svg id="reciprocal-viz" viewBox="0 0 430 303" role="img" aria-label="倒易原胞与 k 星交互示意图"></svg><span class="viz-caption">拖动旋转 · 示意晶格参数</span></div><div class="viz-legend"><span><i></i>选定 k 点</span><span><i class="ring"></i>等价星臂</span><span>虚线 / 倒易基矢</span></div><div class="viz-note"><span>k = (${state.k.map(fraction).join(', ')})</span><span>${r?r.star.length+' 个星臂':'运行计算以显示 k 星'}</span></div></section></div>
 <div class="stats"><div class="stat"><div class="stat-label">小群操作数<small>LITTLE GROUP ORDER</small></div><strong>${r?r.littleGroup.operations.length:'—'}</strong></div><div class="stat"><div class="stat-label">k 星臂数<small>ARMS OF THE k-STAR</small></div><strong>${r?r.star.length:'—'}</strong></div><div class="stat"><div class="stat-label">${r?.littleGroup.antiunitaryIndices.length?'不可约共表示':'不可约表示'}<small>${r?.littleGroup.antiunitaryIndices.length?'IRREDUCIBLE COREPS':'IRREDUCIBLE REPS'}</small></div><strong>${r?(r.littleGroup.antiunitaryIndices.length?r.corepresentations.length:r.irreps.length):'—'}</strong></div></div>
 <section class="panel results"><div class="result-header"><div class="result-heading">计算结果<small>${r?`${esc(gtitle(g))} · k = (${state.k.map(fraction).join(', ')})`:'选择群与波矢后开始计算'}</small></div><div class="result-tools"><button class="text-button" id="export-csv">↓ CSV</button><button class="text-button" id="export-json">↓ JSON</button></div></div><div class="tabs">${[['characters','特征标表'],['operations','对称操作'],['matrices','表示矩阵'],['stars','k 星'],['coreps','磁共表示'],['full','全空间群表示']].map(([t,n])=>`<button data-tab="${t}" class="${state.tab===t?'active':''}">${n}</button>`).join('')}</div><div class="result-content" id="result-content"></div></section>`;
 bindWorkbench();if(state.busy){$$('#app input,#app [data-mode],#app [data-spin],#app .presets button').forEach(e=>e.disabled=true);}renderResults();renderViz();}
function bindWorkbench(){const input=$('#group-search');input.addEventListener('focus',()=>{input.select();showSearch('');});input.addEventListener('input',()=>showSearch(input.value));input.addEventListener('keydown',e=>{if(e.key==='Escape')$('#group-options').classList.add('hidden');if(e.key==='Enter'){e.preventDefault();$('#group-options button')?.click();}});$$('[data-mode]').forEach(b=>b.onclick=()=>selectGroup(list(b.dataset.mode)[b.dataset.mode==='sg'?224:b.dataset.mode==='msg'?1:1],b.dataset.mode));$$('[data-spin]').forEach(b=>b.onclick=()=>{try{readCoords();state.doubleValued=b.dataset.spin==='true';render();}catch(e){showError(e.message);}});$$('[data-preset]').forEach(b=>b.onclick=()=>{state.k=(state.group.kpoints||[{coordinates:[0,0,0]}])[+b.dataset.preset].coordinates.slice();render();});$('#generic-k').onclick=()=>{state.k=[.123,.234,.345];render();};$$('.coords input').forEach(i=>i.onchange=()=>{try{readCoords();render();}catch(e){showError(e.message);}});$('#calculate').onclick=()=>calculate();$$('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;$$('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));renderResults();});$('#export-json').onclick=exportJSON;$('#export-csv').onclick=exportCSV;}
function showSearch(q){q=q.trim().toLowerCase().replace(/\s/g,'');const rows=list(state.mode).filter(g=>[gid(g),g.symbol,g.bcSymbol,g.ogId].some(v=>String(v||'').toLowerCase().replace(/\s/g,'').includes(q))).slice(0,70);const el=$('#group-options');el.classList.remove('hidden');el.innerHTML=rows.length?rows.map(g=>`<button data-select="${esc(gid(g))}"><span>${esc(gid(g))} <b>${esc(gtitle(g))}</b></span><small>${esc(lattices[g.lattice]||'')}${g.type?' · '+['','I','II','III','IV'][g.type]:''}</small></button>`).join(''):'<div class="empty-state">未找到匹配的编号或符号</div>';$$('button',el).forEach(b=>b.onclick=()=>selectGroup(list(state.mode).find(g=>gid(g)===b.dataset.select)));}
function readCoords(){if(state.view==='workbench'&&$('#k-0'))state.k=[0,1,2].map(i=>parseNumber($('#k-'+i).value));}
function compute(payload,action='analyze'){return new Promise((resolve,reject)=>{const id=++requestId;const w=new Worker('compute-worker.js',{type:'module'});worker=w;const timeout=setTimeout(()=>{w.terminate();reject(new Error('计算超过 90 秒，已停止。请尝试较低阶群或一般 k 点。'));},90000);w.onmessage=e=>{if(e.data.id!==id)return;clearTimeout(timeout);w.terminate();e.data.error?reject(new Error(e.data.error)):resolve(e.data.result);};w.onerror=e=>{clearTimeout(timeout);w.terminate();reject(new Error(e.message||'计算模块加载失败'));};w.postMessage({id,action,payload});});}
async function calculate(){if(state.busy)return;try{if(state.view==='workbench'&&$('#group-search')){const raw=$('#group-search').value.trim();if(raw!==(gid()+'   '+gtitle())){const exact=list(state.mode).filter(g=>[gid(g),g.symbol,g.bcSymbol,g.ogId].some(v=>String(v||'').toLowerCase()===raw.toLowerCase()));if(exact.length!==1)throw new Error('请从搜索列表选择唯一的群，或输入完整编号。');state.group=exact[0];}}readCoords();const group=state.group,mode=state.mode;const payload={operations:group.operations,k:state.k.slice(),basis:group.basis,doubleValued:state.doubleValued};state.busy=true;render();const result=await compute(payload);state.result=result;state.resultGroup=group;state.resultMode=mode;state.busy=false;render();toast('计算完成 · 数值一致性检查已通过');}catch(e){state.busy=false;render();showError(e.message);}}
function matrixHTML(m){return `<div class="matrix" style="grid-template-columns:repeat(${m[0]?.length||1},auto)">${m.flat().map(x=>`<span>${typeof x==='number'?fraction(x):esc(cf(x))}</span>`).join('')}</div>`;}
function tableHTML(headers,rows,cls=''){return `<div class="table-wrap"><table class="${cls}"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function renderResults(){const el=$('#result-content');if(!el)return;const r=resultMatches()?state.result:null;if(!r){el.innerHTML=`<div class="empty-state">${state.busy?'<span class="spinner"></span>正在浏览器中构造并验证表示矩阵…':'参数已就绪。点击“计算不可约表示”生成结果。'}</div>`;return;}
 if(state.tab==='characters'){el.innerHTML=`<p class="mini-heading">${r.littleGroup.antiunitaryIndices.length?'幺正子群不可约表示的特征标 · 共表示请查看“磁共表示”':'小群不可约表示 · 每列对应一个操作'}</p>${tableHTML(['表示','维数',...r.littleGroup.unitaryOperations.map((o,i)=>`<span title="操作 ${i+1}">${esc(o.name||'g'+(i+1))}</span>`)],r.irreps.map(ir=>[esc(ir.label),ir.dimension,...ir.characters.map(x=>esc(cf(x)))]))}<div class="note-strip"><span>χ(g) = Tr D(g) · 列序与“表示矩阵”和 JSON 导出一致。</span><span class="badge">✓ 正交性与乘法关系验证</span></div><div class="note-strip"><span>数值标签 D₁… 不等同于原项目的 BC 标准表示标签。</span><span>Σ dᵢ² = ${r.irreps.reduce((s,x)=>s+x.dimension*x.dimension,0)} = |Hₖ|</span></div>`;}
 else if(state.tab==='operations'){el.innerHTML=tableHTML(['#','操作','旋转 R','平移 t','类型'],r.littleGroup.operations.map((o,i)=>[i+1,esc(o.name||'g'+(i+1)),matrixHTML(o.rotation),'('+o.translation.map(fraction).join(', ')+')',o.antiunitary?'<span class="type-dot">反幺正 · T</span>':'幺正']),'operation-table')+'<div class="note-strip">Seitz 操作 {R | t}。表中为模平移子群的代表元；自旋双值使用因子系统，未重复显示带横线的元素。</div>';}
 else if(state.tab==='stars'){el.innerHTML=tableHTML(['星臂','kₓ','kᵧ','k𝓏','生成操作数量'],r.star.map((s,i)=>[i+1,...s.k.map(fraction),s.operationIndices?.length??'—']))+'<div class="note-strip">按倒易整数向量取模。反幺正操作的波矢作用为 −R⁻ᵀk。</div>';}
 else if(state.tab==='matrices'){el.innerHTML=`<div class="controls-row"><label for="irrep-select">选择小群表示</label><select id="irrep-select">${r.irreps.map((ir,i)=>`<option value="${i}">${esc(ir.label)} · ${ir.dimension} 维</option>`).join('')}</select><span class="subtle">矩阵基底由数值对角化选取</span></div><div id="matrix-list" class="matrix-grid"></div>`;const draw=()=>{const ir=r.irreps[+$('#irrep-select').value];$('#matrix-list').innerHTML=ir.matrices.map((m,i)=>`<div class="matrix-box"><div>${i+1} · ${esc(r.littleGroup.unitaryOperations[i]?.name||'g'+(i+1))}</div>${matrixHTML(m)}</div>`).join('');};$('#irrep-select').onchange=draw;draw();}
 else if(state.tab==='coreps'){renderCoreps(el,r);}
 else if(state.tab==='full'){renderFull(el,r);}
}
function renderCoreps(el,r){if(!r.littleGroup.antiunitaryIndices.length){el.innerHTML='<div class="notice">当前小群没有反幺正操作，其表示就是普通不可约表示。可以选择磁空间群或磁点群，并使用 Γ 点查看共表示。</div>';return;}el.innerHTML=tableHTML(['共表示','Wigner 类型','维数','关联小群表示'],r.corepresentations.map((c,i)=>[esc(c.label||'C'+(i+1)),esc(c.type||c.wignerType),c.dimension,esc(c.type==='a'?c.unitaryIrrep:c.type==='b'?'2 × '+c.unitaryIrrep:c.unitaryIrrep+' + '+c.partnerIrrep)]))+'<div class="notice" style="margin-top:16px">反幺正操作表示为 A·K，其中 K 为复共轭。类型 a、b、c 由反幺正陪集的 Wigner 判据确定；双值计算包含 T² = −1。</div><div id="corep-matrices"></div>';const target=$('#corep-matrices');if(r.corepresentations.some(c=>c.matrices)){target.innerHTML=`<div class="controls-row" style="margin-top:18px"><label for="corep-select">查看共表示矩阵</label><select id="corep-select">${r.corepresentations.map((c,i)=>`<option value="${i}">${esc(c.label||'C'+(i+1))} · ${c.dimension} 维</option>`).join('')}</select></div><div class="matrix-grid" id="corep-matrix-list"></div>`;const draw=()=>{const c=r.corepresentations[+$('#corep-select').value];$('#corep-matrix-list').innerHTML=(c.matrices||[]).map((m,i)=>`<div class="matrix-box"><div>${esc(r.littleGroup.operations[i]?.name||'g'+(i+1))}${r.littleGroup.operations[i]?.antiunitary?' · K':''}</div>${matrixHTML(m)}</div>`).join('');};$('#corep-select').onchange=draw;draw();}}
async function renderFull(el,r){
 const reps=r.corepresentations.length?r.corepresentations:r.irreps;
 el.innerHTML=`<div class="controls-row"><label for="full-irrep">诱导自小群${r.corepresentations.length?'共':''}表示</label><select id="full-irrep">${reps.map((ir,i)=>`<option value="${i}">${esc(ir.label)} · ${ir.dimension} 维</option>`).join('')}</select><button class="secondary small" id="induce">生成全空间群表示</button></div><div class="notice">全表示维数 = 小群表示维数 × k 星臂数。反幺正操作的矩阵必须与复共轭 K 一起使用。</div><div id="induction-output"></div>`;
 $('#induce').onclick=async()=>{const b=$('#induce');b.disabled=true;try{const group=state.resultGroup;const destination=$('#induction-output');const full=await compute({group,k:r.k,analysis:r,irrepIndex:+$('#full-irrep').value,doubleValued:r.doubleValued},'induce');if(state.result!==r||!resultMatches()||$('#induction-output')!==destination)return;state.full=full;const output=$('#induction-output');if(!output)return;output.innerHTML=`<div class="controls-row" style="margin-top:20px"><span class="mini-heading">${esc(full.id)} · ${full.dimension} 维 · ${full.star.length} 个星臂</span><button class="text-button" id="export-full">↓ 完整矩阵 JSON</button></div><div class="controls-row"><label for="full-operation">对称操作</label><select id="full-operation">${group.operations.map((o,i)=>`<option value="${i}">${i+1} · ${esc(o.name)}${o.antiunitary?' · K':''}</option>`).join('')}</select></div><div class="table-wrap" style="padding:20px;max-height:420px" id="full-matrix"></div><p class="form-note" id="full-matrix-caption"></p><span class="badge">✓ 诱导表示乘法与平移相位检查通过</span>`;const draw=()=>{const i=+$('#full-operation').value;$('#full-matrix').innerHTML=matrixHTML(full.matrices[i]);$('#full-matrix-caption').textContent=group.operations[i].antiunitary?'此矩阵表示 U·K。反幺正矩阵的迹不是不依赖基底的特征标。':'特征标 χ = '+cf(full.characters[i]);};$('#full-operation').onchange=draw;$('#export-full').onclick=()=>download(JSON.stringify(full,null,2),'full-representation.json');draw();}catch(e){if(state.result===r&&resultMatches()&&$('#induction-output'))$('#induction-output').innerHTML=`<div class="notice error" style="margin-top:16px">${esc(e.message)}</div>`;}finally{b.disabled=false;}};
}
function exportJSON(){if(!resultMatches()){toast('请先运行一次计算');return;}download(JSON.stringify({application:'Symmetry Lab',version:'0.1.0',group:{mode:state.resultMode,id:gid(state.resultGroup,state.resultMode),symbol:gtitle(state.resultGroup)},sources:['https://github.com/goodluck1982/SpaceGroupIrep','https://github.com/goodluck1982/MSGCorep'],notice:'Numerically assigned labels are not BC/Bilbao canonical labels.',...state.result},null,2),`symmetry-${gid(state.resultGroup,state.resultMode)}.json`);}
function exportCSV(){if(!resultMatches()){toast('请先运行一次计算');return;}const r=state.result;const rows=[['irrep','dimension',...r.littleGroup.unitaryOperations.map((o,i)=>o.name||'g'+i)],...r.irreps.map(ir=>[ir.label,ir.dimension,...ir.characters.map(cf)])];download('\uFEFF'+rows.map(row=>row.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n'),'characters.csv','text/csv;charset=utf-8');}

function renderViz(){const svg=$('#reciprocal-viz');if(!svg)return;const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];const dot=(a,b)=>a.reduce((s,x,i)=>s+x*b[i],0);const basis=state.group.basis||[[1,0,0],[0,1,0],[0,0,1]],vol=dot(basis[0],cross(basis[1],basis[2]));const recip=[cross(basis[1],basis[2]),cross(basis[2],basis[0]),cross(basis[0],basis[1])].map(v=>v.map(x=>x/vol));const tocart=k=>[0,1,2].map(i=>k.reduce((s,x,j)=>s+x*recip[j][i],0));const scale=96/Math.max(...recip.map(v=>Math.hypot(...v)));const proj=k=>{const [x,y,z]=tocart(k),a=state.angle,b=state.tilt;const x1=x*Math.cos(a)-y*Math.sin(a),y1=x*Math.sin(a)+y*Math.cos(a);return [215+x1*scale,150+(y1*Math.sin(b)-z*Math.cos(b))*scale];};const draw=()=>{const vertices=[];for(let x of [-.5,.5])for(let y of [-.5,.5])for(let z of [-.5,.5])vertices.push([x,y,z]);let paths='';for(let i=0;i<8;i++)for(let j=i+1;j<8;j++)if(vertices[i].filter((v,d)=>v!==vertices[j][d]).length===1){const a=proj(vertices[i]),b=proj(vertices[j]);paths+=`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="#a6bfad" stroke-width="1.2"/>`;}
 const center=proj([0,0,0]);let axes='';for(let i=0;i<3;i++){const k=[0,0,0];k[i]=.9;const p=proj(k);axes+=`<line x1="${center[0]}" y1="${center[1]}" x2="${p[0]}" y2="${p[1]}" stroke="#bacdc0" stroke-dasharray="3 4"/><text x="${p[0]+6}" y="${p[1]-5}" fill="#809e89" font-size="9" font-family="monospace">b${['₁','₂','₃'][i]}</text>`;}
 const points=resultMatches()?state.result.star.map(s=>s.k.map(x=>x-Math.floor(x+.5))):[state.k];const dots=points.map((k,i)=>{const p=proj(k);return `<circle cx="${p[0]}" cy="${p[1]}" r="${i===0?4:3}" fill="${i===0?'#23785f':'#edf5ec'}" stroke="#23785f" stroke-width="1.3"/>${i===0?`<circle cx="${p[0]}" cy="${p[1]}" r="9" fill="#23785f10"/><text x="${p[0]+11}" y="${p[1]-8}" fill="#286d4d" font-size="12" font-family="serif">${state.k.every(v=>v===0)?'Γ':'k'}</text>`:''}`;}).join('');svg.innerHTML=`<defs><pattern id="grid" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".6" fill="#dce8df"/></pattern></defs><rect width="430" height="303" fill="url(#grid)" opacity=".5"/>${axes}${paths}${dots}`;};draw();let drag=null;svg.onpointerdown=e=>{drag=[e.clientX,e.clientY];svg.setPointerCapture(e.pointerId);svg.style.cursor='grabbing';};svg.onpointermove=e=>{if(!drag)return;state.angle+=(e.clientX-drag[0])*.009;state.tilt=Math.max(-1.3,Math.min(1.3,state.tilt+(e.clientY-drag[1])*.009));drag=[e.clientX,e.clientY];draw();};svg.onpointerup=()=>{drag=null;svg.style.cursor='grab';};}

function renderDatabase(){const groups=list(state.dbMode);const q=state.dbQuery.trim().toLowerCase();const filtered=groups.filter(g=>(state.dbType==='all'||String(g.type)===state.dbType)&&[gid(g,state.dbMode),g.symbol,g.bcSymbol,g.ogId,g.lattice,g.pointGroup].some(v=>String(v||'').toLowerCase().includes(q)));const pageSize=25;state.dbPage=Math.min(state.dbPage,Math.max(0,Math.ceil(filtered.length/pageSize)-1));const selected=filtered.slice(state.dbPage*pageSize,(state.dbPage+1)*pageSize);$('#app').innerHTML=`<section class="panel"><div class="panel-body">${modeButtons(state.dbMode,'db-mode')}<div class="controls-row" style="margin-top:20px"><input id="db-search" placeholder="搜索编号、国际符号、OG 编号或晶格…" aria-label="搜索数据库" value="${esc(state.dbQuery)}">${state.dbMode==='sg'?'':`<select id="db-type" aria-label="磁群类型"><option value="all">全部类型</option>${[1,2,3,4].map(t=>`<option value="${t}" ${String(t)===state.dbType?'selected':''}>Type ${['','I','II','III','IV'][t]}</option>`).join('')}</select>`}<span class="subtle">${filtered.length} 个匹配结果</span></div>${tableHTML([state.dbMode==='sg'?'No.':state.dbMode==='msg'?'BNS':'MPG','国际符号 / BC','晶格',state.dbMode==='msg'?'OG 编号':'点群 / 类型','操作数',''],selected.map(g=>[esc(gid(g,state.dbMode)),`<span class="db-symbol">${esc(gtitle(g))}</span>`,esc(lattices[g.lattice]||g.lattice),esc(state.dbMode==='msg'?g.ogId:g.pointGroup||['','I','II','III','IV'][g.type]),g.operations.length,`<button class="text-button" data-open-group="${esc(gid(g,state.dbMode))}">打开工作台 ↗</button>`]))}<div class="pagination"><span>第 ${state.dbPage+1} / ${Math.max(1,Math.ceil(filtered.length/pageSize))} 页 · 数据来自上游完整表</span><div><button class="secondary small" id="prev-page" ${state.dbPage===0?'disabled':''}>← 上一页</button><button class="secondary small" id="next-page" ${(state.dbPage+1)*pageSize>=filtered.length?'disabled':''}>下一页 →</button></div></div></div></section>`;$$('[data-db-mode]').forEach(b=>b.onclick=()=>{state.dbMode=b.dataset.dbMode;state.dbPage=0;state.dbType='all';state.dbQuery='';renderDatabase();});$('#db-search').oninput=e=>{const pos=e.target.selectionStart;state.dbQuery=e.target.value;state.dbPage=0;renderDatabase();$('#db-search').focus();$('#db-search').setSelectionRange(pos,pos);};if($('#db-type'))$('#db-type').onchange=e=>{state.dbType=e.target.value;state.dbPage=0;renderDatabase();};$('#prev-page').onclick=()=>{state.dbPage--;renderDatabase();};$('#next-page').onclick=()=>{state.dbPage++;renderDatabase();};$$('[data-open-group]').forEach(b=>b.onclick=()=>{state.group=groups.find(g=>gid(g,state.dbMode)===b.dataset.openGroup);state.mode=state.dbMode;state.result=null;state.k=[0,0,0];setView('workbench');calculate();});}

function activeContext(){return `<div class="notice">当前选择：<b>${esc(gtitle())}</b> (${state.mode.toUpperCase()} ${esc(gid())})，k = (${state.k.map(fraction).join(', ')})，${state.doubleValued?'双值':'单值'}。<button class="text-button" data-return-workbench>更改参数 ↗</button></div>`;}
function renderProducts(){
 const group=state.group;const ticket=state.productTicket=(state.productTicket||0)+1;const current=()=>state.view==='products'&&state.productTicket===ticket&&state.group===group;const pf=state.productForm??={k1:state.k.slice(),k2:state.k.slice(),double1:state.doubleValued,double2:state.doubleValued};if(state.mode==='mpg'){pf.k1=[0,0,0];pf.k2=[0,0,0];}
 $('#app').innerHTML=`${activeContext()}<section class="panel" style="margin-top:20px"><div class="panel-top"><div class="panel-title">定义两个 k 星</div><span class="subtle">FULL STAR TENSOR PRODUCT</span></div><div class="panel-body"><div class="workspace-grid">${[1,2].map(n=>`<div><div class="field-label">因子 ${n} · k${n}<span>BC 原胞倒易分数坐标</span></div><div class="coords">${pf['k'+n].map((v,i)=>`<div class="coord"><label for="p${n}-${i}">${['x','y','z'][i]}</label><input id="p${n}-${i}" value="${fraction(v)}" aria-label="因子 ${n} k ${i}" ${state.mode==='mpg'?'disabled':''}></div>`).join('')}</div><div class="inline-row"><label for="pspin-${n}" class="subtle">自旋类型</label><select id="pspin-${n}" class="form-select"><option value="false" ${!pf['double'+n]?'selected':''}>单值</option><option value="true" ${pf['double'+n]?'selected':''}>双值 · SOC</option></select></div></div>`).join('')}</div><button class="primary" id="product-prepare" style="margin-top:12px">计算可选表示 →</button><div id="product-error"></div><div id="product-selection"></div></div></section><section class="panel" style="margin-top:20px"><div class="panel-top"><div class="panel-title">直积分解结果</div><span class="subtle">MOMENTUM SECTORS</span></div><div id="product-output" class="panel-body"><div class="empty-state">选择波矢和自旋类型，再选择两个不可约表示。</div></div></section>`;bindReturn();
 $('#product-prepare').onclick=async()=>{try{pf.k1=[0,1,2].map(i=>parseNumber($('#p1-'+i).value));pf.k2=[0,1,2].map(i=>parseNumber($('#p2-'+i).value));pf.double1=$('#pspin-1').value==='true';pf.double2=$('#pspin-2').value==='true';$('#product-prepare').disabled=true;$('#product-prepare').textContent='正在计算小群表示…';$('#product-error').innerHTML='';$$('#app .coords input,#app [id^="pspin-"]').forEach(i=>i.disabled=true);const params=structuredClone(pf);const a1=await compute({operations:group.operations,basis:group.basis,k:params.k1,doubleValued:params.double1});if(!current())return;const a2=await compute({operations:group.operations,basis:group.basis,k:params.k2,doubleValued:params.double2});if(!current())return;const reps=a=>a.corepresentations.length?a.corepresentations:a.irreps;const saved=JSON.stringify(pf);$('#product-selection').innerHTML=`<div class="product-grid" style="margin-top:20px">${[a1,a2].map((a,n)=>`${n?'<span>⊗</span>':''}<select class="form-select" id="product-${n}">${reps(a).map((r,i)=>`<option value="${i}">${esc(r.label)} · ${r.dimension} × ${a.star.length} = ${r.dimension*a.star.length} 维</option>`).join('')}</select>`).join('')}</div><button class="primary" id="product-run" style="margin-top:16px">分解全 k 星直积 →</button><p class="form-note">每个 D / C 标签只对应其所在波矢和自旋类型。计算自动将双值奇偶性和总波矢带入输出表示。</p>`;
 $('#product-run').onclick=async()=>{const button=$('#product-run');try{if(JSON.stringify(pf)!==saved)throw new Error('参数已变更，请重新计算可选表示。');button.disabled=true;$('#product-output').innerHTML='<div class="empty-state"><span class="spinner"></span>正在解析平移子空间并分解直积…</div>';$$('#app .coords input,#app [id^="pspin-"],#product-prepare,#product-0,#product-1').forEach(i=>i.disabled=true);const payload={group,k1:params.k1,k2:params.k2,analysis1:a1,analysis2:a2,irrepIndex1:+$('#product-0').value,irrepIndex2:+$('#product-1').value,double1:params.double1,double2:params.double2};const result=await compute(payload,'product');if(!current())return;state.productResult=result;$('#product-output').innerHTML=`<div class="notice">${esc(result.left.id)} (${result.left.dimension} 维) ⊗ ${esc(result.right.id)} (${result.right.dimension} 维) · 输出为${result.doubleValued?'双值':'单值'}表示 · 总维数 ${result.productDimension} = ${result.decomposedDimension}</div><div style="margin-top:18px">${tableHTML(['输出 k','星臂数','不可约分量','全表示维数','重数'],result.outputs.flatMap(o=>o.terms.map(t=>['('+o.k.map(fraction).join(', ')+')',o.star.length,esc(t.label||t.id),t.dimension,t.multiplicity])))}</div><div class="note-strip"><span>✓ 总维数守恒 · 平移本征空间与特征标重构通过</span><button class="text-button" id="export-product">↓ 完整结果 JSON</button></div>`;$('#export-product').onclick=()=>download(JSON.stringify(result,null,2),'star-product.json');}catch(e){if(!current())return;$('#product-error').innerHTML=`<div class="notice error" style="margin-top:14px">${esc(e.message)}</div>`;}finally{if(current()){$$('#app .coords input,#app [id^="pspin-"],#product-prepare,#product-0,#product-1').forEach(i=>i.disabled=state.mode==='mpg'&&i.tagName==='INPUT');button.disabled=false;}}};
 for(const input of $$('#app .coords input,#app [id^="pspin-"]'))input.addEventListener('change',()=>{$('#product-selection').innerHTML='';});
 }catch(e){if(!current())return;$('#product-error').innerHTML=`<div class="notice error" style="margin-top:14px">${esc(e.message)}</div>`;}finally{if(current()){$('#product-prepare').disabled=false;$('#product-prepare').textContent='计算可选表示 →';$$('#app .coords input,#app [id^="pspin-"]').forEach(i=>i.disabled=state.mode==='mpg'&&i.tagName==='INPUT');}}};
}
function decompositionText(terms){const data=Array.isArray(terms)?terms:terms.terms||terms.decomposition||terms.multiplicities||[];return data.filter(t=>(t.multiplicity??t.coefficient??t.count??0)>0).map(t=>`${(t.multiplicity??t.coefficient??t.count)>1?(t.multiplicity??t.coefficient??t.count)+' ':''}${t.label||t.irrep?.label||t.irrepId||t.id}`).join(' ⊕ ')||JSON.stringify(terms);}
function bindReturn(){$$('[data-return-workbench]').forEach(b=>b.onclick=()=>setView('workbench'));}

function renderBands(){const r=resultMatches()?state.result:null;$('#app').innerHTML=`${activeContext()}<div class="workspace-grid" style="margin-top:20px"><section class="panel"><div class="panel-top"><div class="panel-title">载入能带数据</div><span class="subtle">LOCAL FILE</span></div><div class="panel-body"><div class="controls-row"><label class="secondary small" for="trace-file">↑ 打开 trace.txt / JSON</label><input type="file" id="trace-file" class="sr-only" accept=".txt,.json,.dat"><button class="text-button" id="band-template">JSON 模板</button><button class="text-button" id="load-trace-example">载入真实示例</button></div><p class="form-note">trace 必须来自对应群的 BC 原胞；此版本不执行任意 POSCAR 晶胞到 BC 的转换。文件只在本机读取。</p><textarea class="band-input" id="band-data" aria-label="能带特征标 JSON 或 trace 内容" placeholder='{"bands":[{"index":1,"energy":-1.2,"characters":[1,1]}]}'>${esc(state.bandText)}</textarea><button class="primary" id="band-run" ${state.busy?'disabled':''}>解析并匹配表示 →</button><div id="band-error"></div></div></section><section class="panel"><div class="panel-top"><div class="panel-title">匹配结果</div><span class="subtle">CHARACTER MATCHING</span></div><div class="panel-body" id="band-output"><div class="empty-state">导入文件后显示能级、简并度与表示分解。<br>JSON 的特征标顺序须与当前幺正操作顺序一致。</div></div></section></div><div class="notice" style="margin-top:20px">匹配使用完整特征标向量，拒绝非整数或无法重构的分解。结果使用数值标签，不自动转换为 BC / Bilbao 标准能带标签。</div>`;bindReturn();$('#band-data').oninput=e=>state.bandText=e.target.value;$('#trace-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024){toast('文件超过 10 MiB，请使用较小的 k 点区间');return;}state.bandText=await file.text();$('#band-data').value=state.bandText;toast(`已载入 ${file.name}`);};$('#band-template').onclick=()=>{if(!r){toast('请先在工作台运行计算');return;}download(JSON.stringify({description:'填写真实能带特征标，按照 operations 列序。此模板不包含示例计算结果。',group:{id:gid(),mode:state.mode},k:state.k,doubleValued:state.doubleValued,operations:r.littleGroup.unitaryOperations,bands:[]},null,2),'band-template.json');};$('#band-run').onclick=()=>runBands();$('#load-trace-example').onclick=async()=>{state.bandText=await (await fetch('examples/trace-msg.txt')).text();state.mode='msg';state.group=databases.msg.groups.find(g=>g.id==='166.101');state.k=[0,0,0];state.doubleValued=true;state.result=null;await calculate();if(state.view==='bands')runBands();};}
async function runBands(){const out=$('#band-output'),err=$('#band-error');err.innerHTML='';try{const text=$('#band-data').value.trim();if(!text)throw new Error('请选择文件或输入数据。');const r=resultMatches()?state.result:null;if(!r)throw new Error('请先在工作台计算对应群、k 点和自旋类型。');$('#band-run').disabled=true;let rows=[];if(text.startsWith('{')){const obj=JSON.parse(text);if(obj.k&&obj.k.some((v,i)=>Math.abs(v-state.k[i])>1e-8))throw new Error('JSON 的 k 点与当前计算不一致。');if(obj.doubleValued!==undefined&&obj.doubleValued!==state.doubleValued)throw new Error('JSON 自旋类型与当前计算不一致。');if(obj.group&&(String(obj.group.id)!==gid()||obj.group.mode!==state.mode))throw new Error('JSON 群编号与当前选择不一致。');if(!Array.isArray(obj.bands)||!obj.bands.length)throw new Error('bands 必须是非空能带数组。');rows=obj.bands.map((b,i)=>({index:b.index??i+1,energy:b.energy,degeneracy:b.degeneracy,k:state.k,terms:decomposeBand((b.characters||[]).map(complex),r)}));}else{const {parseTrace,matchTraceOperations,charactersForAnalysis}=await import('./trace-parser.js');const trace=parseTrace(text);if(Boolean(trace.soc)!==state.doubleValued)throw new Error('trace 的 SOC 标记与当前单值 / 双值选择不一致。');const matched=matchTraceOperations(trace,state.group);const point=matched.kpoints.find(p=>p.k.every((v,i)=>Math.abs(v-state.k[i]-Math.round(v-state.k[i]))<1e-7));if(!point)throw new Error('文件中未找到当前 k 点。请在工作台输入文件中的 k 坐标。');rows=point.bands.map(b=>{const chars=charactersForAnalysis(point,b,r).map(complex);return {...b,k:point.k,terms:decomposeBand(chars,r)};});}
 for(const row of rows){if(row.terms.dimension<=0)throw new Error('能带表示的维数必须大于零。');if(row.degeneracy!==undefined&&row.terms.dimension!==row.degeneracy)throw new Error('能带 '+row.index+' 的简并度与特征标分解维数不一致。');}out.innerHTML=tableHTML(['能带','能量 / eV','表示分解'],rows.map(b=>[esc(b.index),typeof b.energy==='number'?b.energy.toFixed(6):'—',esc(decompositionText(b.terms))]))+`<p class="form-note">已匹配 ${rows.length} 个能级。${r.corepresentations.length?'已按共表示限制的正确范数匹配 a / b / c 型；使用本页面数值标签。':''}</p><button class="text-button" id="export-bands">↓ 导出能带匹配 JSON</button>`;$('#export-bands').onclick=()=>download(JSON.stringify({group:{id:gid(),mode:state.mode},k:r.k,doubleValued:r.doubleValued,bands:rows},null,2),'band-representations.json');}catch(e){err.innerHTML=`<div class="notice error" style="margin-top:14px">${esc(e.message)}</div>`;}finally{if($('#band-run'))$('#band-run').disabled=false;}}

function renderDocs(){$('#app').innerHTML=`<div class="docs-layout"><section class="panel prose"><h2>对称性计算，在浏览器里完成</h2><p>本网站将 SpaceGroupIrep 与 MSGCorep 的开放群数据转换为 JSON，并使用 JavaScript 重新构造有限小群的投影表示。无需后端计算服务；读取的本地文件不会上传。它是原项目功能的浏览器移植版本，尚未覆盖全部原始接口。</p><h3>从一次计算开始</h3><ol><li>选择 SG、MSG 或 MPG，搜索群编号或国际符号。</li><li>输入 BC 原胞倒易基矢下的波矢，支持 <code>1/2</code> 等分数。</li><li>选择单值或双值表示，点击计算。</li><li>检查特征标、表示矩阵、群操作和数值验证，导出 JSON / CSV。</li></ol><h3>坐标与可视化</h3><p>操作 {R | t} 使用 BC 直接原胞的分数坐标。波矢使用对应倒易分数坐标，幺正操作作用为 R⁻ᵀk，反幺正操作为 −R⁻ᵀk。平移相位为 exp(−2πi k·t)。磁群使用 BNS family 的 BC 原胞。</p><p>右侧显示倒易原胞示意图，不是 Wigner–Seitz 布里渊区。晶格常数采用示意值，不能用于定量长度和角度比较。部分高对称点名称依赖 BZ 类型；按钮悬停可查看所属 BZ，实际计算始终按输入坐标进行。</p><h3>表示构造与验证</h3><p>在有限平移商群上构造含 Bloch 与自旋因子的正则表示，通过厄米对易算符分解不可约子空间。双值计算使用上游自旋旋转矩阵；反幺正共表示包含复共轭与自旋时间反演。</p><p>计算结果必须通过维数平方和、特征标正交性及表示乘法关系检查。JSON 保留验证误差。失败时显示错误，不以预置结果替代。</p><div class="notice warning">D₁、D₂… 和 C₁、C₂… 是当前计算的数值编号。它们不是 Bradley–Cracknell 或 Bilbao 的标准标签。数值基底和原文矩阵可存在相似变换，不应按矩阵元素逐项直接比较。</div></section>
 <section class="panel prose"><h2>当前功能覆盖</h2><table><thead><tr><th>功能</th><th>状态</th></tr></thead><tbody><tr><td>230 SG、1651 MSG、122 MPG 数据</td><td>已实现</td></tr><tr><td>BNS / OG 编号与符号检索</td><td>已实现</td></tr><tr><td>任意数值 k 点的小群与 k 星</td><td>已实现</td></tr><tr><td>单值 / 双值小群不可约表示</td><td>已实现 · 数值标签</td></tr><tr><td>磁小群 Wigner 类型与共表示</td><td>已实现 · 数值标签</td></tr><tr><td>SG / MSG 全 k 星诱导表示</td><td>已实现</td></tr><tr><td>SG / MSG 任意 k 星直积</td><td>已实现</td></tr><tr><td>trace / JSON 能带表示匹配</td><td>已实现 · BC 原胞输入</td></tr><tr><td>磁点群共表示直积</td><td>已实现</td></tr><tr><td>BC / Bilbao 标准标签映射</td><td>尚未移植</td></tr><tr><td>任意 POSCAR / CIF → BC 晶胞</td><td>尚未移植</td></tr></tbody></table><h3>可复现与开放源码</h3><p>程序、数据与数值算法随静态网站提供。<a href="source.zip" download>下载网站完整源代码</a>。该版本遵循 <a href="licenses/MSGCorep-GPL-3.0.txt">GPL-3.0</a>；上游作者 Gui-Bin Liu 等人的声明与许可证保留。</p><h3>如何解释结果</h3><p>普通小群表示列出幺正操作的特征标。磁共表示的反幺正矩阵必须与 K 一起使用，不能当作普通线性表示。能带匹配由幺正特征标确定共表示分解，磁小群匹配使用共表示限制的归一化范数；标准标签请使用原 MSGCorep。</p></section>
 <section class="panel prose full-span"><h2>项目来源与文献</h2><div class="workspace-grid"><div><h3>SpaceGroupIrep</h3><p><a target="_blank" rel="noreferrer" href="https://github.com/goodluck1982/SpaceGroupIrep">goodluck1982 / SpaceGroupIrep ↗</a><br>空间群生成元、BC 原胞旋转、k 点表及表示元数据。<br><a href="https://doi.org/10.1016/j.cpc.2021.107993" target="_blank" rel="noreferrer">Computer Physics Communications 265, 107993 (2021)</a></p></div><div><h3>MSGCorep</h3><p><a target="_blank" rel="noreferrer" href="https://github.com/goodluck1982/MSGCorep">goodluck1982 / MSGCorep ↗</a><br>磁群编号、磁群操作、自旋矩阵及磁点群数据。<br><a href="https://doi.org/10.1016/j.cpc.2023.108722" target="_blank" rel="noreferrer">Computer Physics Communications 288, 108722 (2023)</a></p></div></div><p>使用这些数据发表研究时，请引用原始软件和论文。本网站为独立浏览器实现，不代表原项目作者发布或背书。</p></section></div>`;}

document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav)setView(nav.dataset.view);if(!e.target.closest('.search-wrap'))$('#group-options')?.classList.add('hidden');});$('#help-button').onclick=()=>setView('docs');$('#export-top').onclick=exportJSON;
try{const [sg,msg,mpg]=await Promise.all(['space-groups','magnetic-groups','points'].map(async name=>{const r=await fetch(`data/${name}.json`);if(!r.ok)throw new Error(`${name} 数据加载失败`);return r.json();}));databases={sg,msg,mpg};state.group=sg.groups.find(g=>g.number===225);$('#data-status').textContent='本地引擎 · 数据就绪';render();await calculate();}catch(e){$('#app').innerHTML=`<div class="notice error">${esc(e.message)}。请刷新页面重试，或通过 HTTP 静态服务器打开网站。</div>`;$('#data-status').textContent='加载失败';}
